  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can explain, with a concrete circuit example, why current is the same at all points in a series loop and why potential difference is what is used up across components, then correctly solve a small set of course-appropriate circuit problems using that distinction."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I confuse current with potential difference and cannot explain why circuit rules hold. Prepare for independent problem solving.",
          "explanation": "The learner reports a specific conceptual confusion between current and potential difference and cannot explain why circuit rules hold. No execution history, saved checks or readiness evidence exists, so I treat the learner as a beginner in this topic but do not assume they need preparatory lessons beyond the accepted goal. The smallest useful strategy is a short conceptual core that directly addresses the confusion, followed by guided application to a few representative circuit problems, then independent changed problems. I keep the scope tight because the accepted outcome is independent problem solving, not a full circuit theory course, and because no assessment weights or deadlines are known. I defer deeper analysis of series/parallel rules and multi-loop problems until the learner has demonstrated the basic distinction and simple application.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 240
          },
          "phases": [
            {
              "localId": "phase_1",
              "title": "Conceptual foundation",
              "outcome": "The learner can state the difference between current and potential difference and use it to explain why current is continuous in a series loop and why potential difference is divided across components.",
              "effort": {
                "lowMinutes": 30,
                "likelyMinutes": 50,
                "highMinutes": 80
              },
              "readinessCriterion": "The learner explains, without help, why current is the same at all points in a series loop and why potential difference is used up across components, using a concrete circuit example."
            },
            {
              "localId": "phase_2",
              "title": "Guided application",
              "outcome": "The learner correctly solves representative circuit problems by applying the current/potential difference distinction and conservation rules, with reference material available.",
              "effort": {
                "lowMinutes": 40,
                "likelyMinutes": 60,
                "highMinutes": 100
              },
              "readinessCriterion": "The learner solves at least three representative problems correctly, explaining each step in terms of current and potential difference."
            },
            {
              "localId": "phase_3",
              "title": "Independent problem solving",
              "outcome": "The learner independently solves changed circuit problems, choosing appropriate methods and justifying each choice.",
              "effort": {
                "lowMinutes": 20,
                "likelyMinutes": 40,
                "highMinutes": 60
              },
              "readinessCriterion": "The learner solves two changed problems correctly without assistance, explaining method choice and checking results."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Core conceptual target: the learner must distinguish current from potential difference and explain how potential difference drives current."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Needed to explain why circuit rules hold: conservation of charge (current continuity) and conservation of energy (potential difference sum)."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Applied goal: independent problem solving using the concepts from scope_1 and scope_2."
          }
        ],
        "activities": [
          {
            "localId": "concept_core",
            "outcomeRefs": [
              "phase_1"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Distinguish current and potential difference",
