providerResponses.text:
{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can correctly choose and justify a method (Ohm's law, series/parallel equivalents, or KCL/KVL) on 3 unfamiliar circuits and solve them correctly without assistance."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I can explain voltage and current but choose the wrong law on unfamiliar circuits. Focus on selecting and applying the method.",
          "explanation": "The accepted outcome is method-selection capability on unfamiliar circuits, not more explanation of voltage and current. There is no assessment weight, deadline or recent evidence supplied, so the plan targets the smallest useful capability check: one integrated activity in which the learner chooses a method, states a valid selection reason, solves the circuit and checks the result on changed, course-appropriate problems. The learner is told to use only methods actually taught in their course, so the task stays within the real repertoire and does not assume advanced techniques. No separate preparatory lessons are booked because the stated weakness is method choice, not missing voltage/current concepts, and the integrated task can diagnose and address both selection and application. Further remediation is contingent on an observed failure at that checkpoint rather than compulsory.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 60,
            "highMinutes": 90
          },
          "phases": [
            {
              "localId": "selection",
              "title": "Method selection and application on unfamiliar circuits",
              "outcome": "Correctly choose, justify and apply a taught circuit method to unfamiliar circuits and check the results.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "Correct method choice, valid selection reason and correct solution on 3 changed course-appropriate circuits without assistance."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The whole learning target: selecting and applying the right circuit method on unfamiliar circuits, addressed by one integrated method-selection activity and a contingent remedial activity if the checkpoint fails."
          }
        ],
        "activities": [
          {
            "localId": "method_selection_set",
            "outcomeRefs": [
              "selection"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Choose and apply the right method on unfamiliar circuits",
            "activityType": "Method-selection practice with worked reasoning",
            "purpose": "Diagnose and improve method choice by requiring an explicit selection reason and a checked solution for each unfamiliar circuit, using only methods already taught.",
            "instructions": "Use only circuit-analysis methods you have already been taught in your course (for example Ohm's law, series/parallel equivalent resistance, voltage/current division, KCL/KVL node or loop analysis, or source transformation if taught). Do not use advanced methods you have not learned. Work through 3 unfamiliar circuits of the type your course uses. For each circuit: (1) redraw it if helpful and label the known and unknown quantities; (2) state which taught method you will use and why it applies to this circuit's topology and assumptions; (3) solve for the requested quantity, showing each step; (4) verify your answer by an independent check (for example a different taught method where valid, a power balance, or substituting back into the equations). If your course problems are not available, create 3 changed circuits yourself at the same level and note the values you chose. At the end, write a short summary of the cues that told you which method to choose (for example number of independent nodes, presence of parallel branches, whether sources are independent). If you get a circuit wrong, correct that actual circuit, explain the error in method choice or execution, and re-check the corrected solution.",
            "completionCriterion": "For 3 changed, course-appropriate circuits, you correctly choose a taught method, give a valid selection reason, reach the correct solution, and show an independent check for each; any errors are corrected and explained. No assistance during the final solutions.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 90,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 30,
                "completionCriterion": "First unfamiliar circuit solved with method choice, reason, solution and check recorded."
              },
              {
                "afterMinutes": 60,
                "completionCriterion": "Second unfamiliar circuit solved with method choice, reason, solution and check recorded."
              }
            ]
          },
          {
            "localId": "remedial_method_drill",
            "outcomeRefs": [
              "selection"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted method-choice remediation",
            "activityType": "Focused remedial drill",
            "purpose": "Repair a specific method-selection failure observed at the checkpoint by drilling the misapplied method category before retrying the checkpoint.",
            "instructions": "This activity is only done if the checkpoint activity shows a specific method-selection failure. Review the exact circuit where you chose the wrong method. Write the decision rule that distinguishes the correct method from the one you used (what feature of the circuit, such as node count or source type, tells you which to use). Then solve 2 new circuits of that same category, stating the method and reason before each solution and checking each answer. If you still choose the wrong method, repeat once more with 2 further circuits only in that category.",
            "completionCriterion": "You correctly choose, justify and solve 2 new circuits in the previously failed category, with checks, without repeating the original selection error.",
            "effort": {
              "lowMinutes": 25,
              "likelyMinutes": 40,
              "highMinutes": 60
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "method_selection_set",
                "condition": "On the method-selection set you choose a wrong method for at least one circuit or cannot give a valid selection reason."
              }
            },
            "hardDependencies": [
              "method_selection_set"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has been taught at least one valid circuit-analysis method in their course; the activity restricts use to those taught methods.",
            "No assessment weight, deadline or recent performance evidence was supplied, so the plan is driven by the stated weakness alone."
          ],
          "tradeOffs": [
            "Chose one integrated method-selection activity plus a contingent remedial drill instead of a full teach-practice-test sequence, because the stated weakness is method choice rather than missing voltage/current concepts.",
            "Deferred broader exam technique and timed paper practice because no assessment date or weight is known."
          ],
          "unresolvedUncertainty": [
            "Which specific methods the learner's course has taught is unknown; the instructions handle this by restricting the learner to their own taught repertoire.",
            "Whether the learner can already select methods correctly is unknown; the checkpoint activity will provide the first real evidence."
          ],
          "stoppingConditions": [
            "Stop when the learner correctly chooses, justifies, solves and checks 3 changed course-appropriate circuits without assistance.",
            "If the checkpoint is passed, do not book further method-selection work unless new evidence of weakness appears."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "This plan spends the first checkpoint on method selection and application rather than on re-explaining voltage and current, because the accepted outcome is choosing the right law on unfamiliar circuits. It commits one integrated activity with genuine split points inside a 90-minute timebox so the learner can stop at a meaningful point after each solved circuit. A second remedial activity is contingent on a concrete observed failure at that checkpoint, so no extra work is added if the learner already selects methods correctly. No timed exam practice, paper analysis or broad revision is included because no assessment date, weight or cycle was supplied."
}

