{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "By the end of 2026-10-09 you have worked the actual teacher quiz items, explained the current/voltage and series/parallel reasoning behind each answer, and corrected your own errors, so you can walk into the quiz on 2026-10-10 with a checked set of worked solutions."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "My teacher-written circuit quiz is in two days. I need a defensible short plan; explicitly explain anything sacrificed. There are no verified topic weights.",
          "explanation": "Two days remain with only 25 available minutes on 2026-10-08 and 25 on 2026-10-09; the quiz day and all later days are excluded. With no verified topic weights and no readiness evidence, the defensible move is to spend the available time on the actual quiz material rather than on invented practice sets. The quiz is teacher-written, so the highest-value work is obtaining and working through the real items, explaining the current/voltage and series/parallel reasoning in each, and correcting errors. Current/voltage is treated as the foundational prerequisite and is integrated into the same work rather than given a separate preparatory lesson. Mixed circuits are deferred: without verified weights and with only 50 usable minutes, spreading across four topics would leave none of them checked. The plan is deliberately small — two short sessions on the actual assignment, ending before the quiz day.",
          "recommendedEffort": {
            "lowMinutes": 40,
            "likelyMinutes": 50,
            "highMinutes": 50
          },
          "phases": [
            {
              "localId": "phase_quiz",
              "title": "Work the actual quiz items",
              "outcome": "The real teacher quiz items are solved, explained and checked, with errors corrected.",
              "effort": {
                "lowMinutes": 40,
                "likelyMinutes": 50,
                "highMinutes": 50
              },
              "readinessCriterion": "You can explain the current/voltage and series/parallel reasoning for each worked quiz item and show corrected solutions."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Foundational current and voltage reasoning is explained and applied inside the actual quiz items rather than taught separately."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Series-circuit items in the actual quiz are solved and checked, with the series current/voltage rules stated as they are used."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Parallel-circuit items in the actual quiz are solved and checked, with the parallel current/voltage rules stated as they are used."
          },
          {
            "scopeRef": "scope_4",
            "disposition": "DEFERRED",
            "contribution": "Mixed circuits are not worked in this two-day window; any mixed item appearing in the actual quiz is handled by decomposing it into the series and parallel parts already practised.",
            "reason": "With only 50 usable minutes before the quiz and no verified topic weights, adding mixed-circuit practice would spread effort too thinly to leave any topic checked; mixed circuits are better handled reactively if they appear in the actual items."
          }
        ],
        "activities": [
          {
            "localId": "quiz_work",
            "outcomeRefs": [
              "phase_quiz"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Work, explain and check the actual teacher quiz items",
            "activityType": "Assignment completion with explanation and error correction",
            "purpose": "To solve the real quiz items, state the current/voltage and series/parallel reasoning behind each answer, and correct actual errors before the quiz.",
            "instructions": "Obtain the actual teacher-written quiz (or the exact items your teacher provided). Work through each item in order. For every item: (1) write the given values and what is asked; (2) state which rule you are using and why it applies (for example, in a series branch the current is the same through each component, so voltages add; in parallel branches the voltage is the same across each branch, so currents add); (3) solve showing your steps; (4) check your answer against the item's own data (for example, confirm the branch currents sum to the total current, or the component voltages sum to the source voltage). If an item involves a combination of series and parallel parts, split it into those parts and apply the same rules. When you find an error, mark it, explain what rule you misapplied, and re-solve that item correctly. If you cannot obtain the actual items, tell me and we will use only the items the teacher has given you — do not substitute invented questions. Do not spend time on mixed-circuit practice beyond what the actual items require.",
            "completionCriterion": "Every actual quiz item has a written solution, a stated rule and reason, a check, and any error found is corrected with an explanation of the misapplied rule.",
            "effort": {
              "lowMinutes": 40,
              "likelyMinutes": 50,
              "highMinutes": 50
            },
            "timeboxMinutes": 50,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 25,
                "completionCriterion": "The first portion of the actual quiz items is solved, explained and checked, with errors corrected."
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The quiz is teacher-written and the actual items are available to the learner.",
            "No verified topic weights exist, so effort is allocated to the actual assignment rather than to guessed topic weights."
          ],
          "tradeOffs": [
            "Mixed circuits (scope_4) are deferred so that current/voltage, series and parallel items can be worked and checked within the 50 available minutes.",
            "No separate preparatory lesson on current and voltage is scheduled; that reasoning is explained inside the actual quiz items instead."
          ],
          "unresolvedUncertainty": [
            "Whether the actual quiz contains mixed-circuit items is unknown; if it does, they will be handled by decomposing into series and parallel parts already practised.",
            "Without verified topic weights, the relative importance of each topic cannot be confirmed."
          ],
          "stoppingConditions": [
            "Stop when every actual quiz item has a checked solution and corrected errors, or when the 50 available minutes are used, whichever comes first."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "With only 25 minutes on 2026-10-08 and 25 on 2026-10-09 before the 2026-10-10 quiz, and no verified topic weights, the plan sacrifices mixed-circuit practice (scope_4) and any separate current/voltage lesson so that the actual teacher-written items can be solved, explained and checked. This keeps the work bounded and focused on the real assessment rather than on invented practice."
}

