{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can explain Bayes' rule in your own words and correctly solve a changed medical-test probability problem, clearly separating the base rate from the test sensitivity."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "MASTERY",
          "outcome": "Develop the ability to explain Bayes’ rule and apply it to a changed medical-test probability example. I confuse the base rate with sensitivity.",
          "explanation": "The learner's stated weakness is confusing the base rate with sensitivity, so the plan starts by making base rates and conditional probability explicit before deriving Bayes' rule. The core activity integrates explanation, supported application and an independent changed example, which is sufficient for this bounded goal. A contingent remediation activity is offered only if the core task reveals a concrete failure, avoiding unnecessary preparatory work.",
          "recommendedEffort": {
            "lowMinutes": 60,
            "likelyMinutes": 90,
            "highMinutes": 150
          },
          "phases": [
            {
              "localId": "understand_bayes",
              "title": "Understand and apply Bayes' rule",
              "outcome": "Explain Bayes' rule and correctly apply it to a changed medical-test example, distinguishing base rate from sensitivity.",
              "effort": {
                "lowMinutes": 60,
                "likelyMinutes": 90,
                "highMinutes": 150
              },
              "readinessCriterion": "You can state Bayes' rule, identify the base rate and sensitivity in a new problem, and compute the correct posterior probability."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Essential prerequisite: understanding base rates and conditional probability is necessary to avoid confusing them with sensitivity."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Core target: Bayes' rule is the central tool to be explained and applied."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Transfer is required to demonstrate mastery on a changed medical-test example."
          }
        ],
        "activities": [
          {
            "localId": "bayes_core",
            "outcomeRefs": [
              "understand_bayes"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Explain and apply Bayes' rule to a changed medical-test example",
            "activityType": "integrated_explanation_and_application",
            "purpose": "Develop and demonstrate the ability to explain Bayes' rule and correctly apply it to a changed medical-test probability example, explicitly distinguishing base rate from sensitivity.",
            "instructions": "1. Write a clear explanation of Bayes' rule in your own words, including what each term (prior, likelihood, evidence, posterior) represents. 2. Choose a medical-test probability problem that is different from any you have seen before. It must involve a disease prevalence (base rate), a test sensitivity, and a test specificity (or false positive rate). Clearly identify which number is the base rate and which is the sensitivity. 3. Solve the problem step by step using Bayes' rule, showing your substitution and arithmetic. 4. Check your answer by computing the same posterior using a natural-frequency (count) approach or a probability tree, and confirm both methods agree. 5. In 2–3 sentences, explain why confusing the base rate with the sensitivity would lead to a wrong answer in your example. If you cannot find a suitable problem, create one with realistic numbers and state them explicitly.",
            "completionCriterion": "You produce a correct explanation of Bayes' rule, correctly identify the base rate and sensitivity in your chosen problem, compute the correct posterior probability using Bayes' rule, verify it with a second method, and clearly articulate the distinction between base rate and sensitivity.",
            "effort": {
              "lowMinutes": 60,
              "likelyMinutes": 90,
              "highMinutes": 150
            },
            "timeboxMinutes": 90,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "bayes_remediation",
            "outcomeRefs": [
              "understand_bayes"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Targeted remediation on base rate versus sensitivity confusion",
            "activityType": "remediation",
            "purpose": "Address a concrete observed failure in distinguishing base rate from sensitivity with focused practice and explanation.",
            "instructions": "1. Review your work from the core activity and identify exactly where you confused the base rate with the sensitivity. 2. Write a short explanation of the difference between the two, using your own example. 3. Solve two additional medical-test problems, each time explicitly labeling the base rate and sensitivity before computing. 4. Check your answers and explain how you avoided the confusion this time.",
            "completionCriterion": "You correctly label base rate and sensitivity in two new problems, compute the correct posterior probabilities, and explain how you avoided the previous confusion.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "bayes_core",
                "condition": "In the core activity, you incorrectly identify the base rate or sensitivity, or your computed posterior is wrong because you confused the two."
              }
            },
            "hardDependencies": [
              "bayes_core"
            ]
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "The core activity integrates explanation, application and transfer to keep the plan efficient; additional practice is contingent on demonstrated confusion rather than required upfront."
          ],
          "unresolvedUncertainty": [
            "No prior evidence of readiness is available, so the plan begins with a self-contained integrated task that includes necessary explanation and support."
          ],
          "stoppingConditions": [
            "Stop when you can explain Bayes' rule and correctly solve a changed medical-test problem, distinguishing base rate from sensitivity."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
