{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You finish one small loops-and-dictionaries workbook: you write a loop that totals a small list of numbers, build a dictionary of totals by category, and print each category total, then explain in one sentence why the dictionary keys match the category names. That is the shared prerequisite both report targets depend on."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Prepare a CSV report that totals expenses by category, using loops and dictionaries, with the shared loops/dictionary prerequisite owned once by plan_1.",
          "explanation": "You are new to loops and dictionaries, so the useful next checkpoint is one small integrated workbook that teaches both constructs and produces a real category-totals result. The CSV report itself stays strategic until that checkpoint works: once you can loop and total with a dictionary, formatting the same totals as CSV is a small later step. The shared prerequisite is owned here and counted once; plan_2 depends on it rather than duplicating it.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 60,
            "highMinutes": 90
          },
          "phases": [
            {
              "localId": "prereq",
              "title": "Loops and dictionaries prerequisite",
              "outcome": "You can loop over a list, accumulate totals, store category totals in a dictionary, and print them.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "You produce correct category totals and explain why the dictionary keys match the category names."
            },
            {
              "localId": "csv_report",
              "title": "CSV totals report (strategic)",
              "outcome": "You write the same totals as CSV rows with a header, using the loops and dictionary skills from the prerequisite."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Taught and demonstrated in the shared loops-and-dictionaries workbook; owns the prerequisite for both report targets."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Strategic CSV output target; becomes a small formatting step once the shared loops-and-dictionaries prerequisite is demonstrated."
          }
        ],
        "activities": [
          {
            "localId": "loops_dict_workbook",
            "outcomeRefs": [
              "prereq"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Loops and dictionaries workbook: category totals",
            "activityType": "Guided coding workbook",
            "purpose": "Teach loops and dictionaries through one small real task that both report targets need.",
            "instructions": "Use Python. Work through these steps in one file. 1) Start with this small expense list: expenses = [('food', 12), ('travel', 30), ('food', 8), ('books', 20)]. 2) Write a for loop that prints each item, so you see the loop structure. 3) Write a second loop that accumulates a running total of all amounts and print the grand total. 4) Create an empty dictionary totals = {}. Write a loop that adds each amount to totals[category], creating the key if it is not there yet. 5) Print each category and its total by looping over totals.items(). 6) Check the result by hand: food should be 20, travel 30, books 20, grand total 70. 7) Write one sentence explaining why the dictionary keys match the category names in the expense list. If the dictionary step is unclear, re-read your own loop from step 3 and describe what changes when the accumulator is a dictionary instead of a single number.",
            "completionCriterion": "Your program prints each category total (food 20, travel 30, books 20) and the grand total 70, and you write a one-sentence explanation that the dictionary key is the category name taken from each tuple.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "You have Python available and can run a single script file.",
            "You have no prior loops or dictionary experience, based on your statement that you are new to both."
          ],
          "tradeOffs": [
            "The CSV formatting target is deferred so the first committed work teaches the shared prerequisite instead of producing a report by copy-paste.",
            "One integrated workbook is used rather than separate loop and dictionary lessons, because the two constructs are needed together for category totals."
          ],
          "unresolvedUncertainty": [
            "Your exact Python version and editor are unknown, but the workbook only needs basic Python 3 features."
          ],
          "stoppingConditions": [
            "Stop after the workbook prints the correct category totals and grand total and you have explained the dictionary-key match.",
            "Do not start the CSV report until the workbook checkpoint is demonstrated."
          ]
        }
      }
    },
    {
      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report with totals by category, using the shared loops/dictionary prerequisite owned by plan_1 and not duplicating it.",
          "explanation": "The JSON report uses the same loops-and-dictionary prerequisite as the CSV target, so plan_2 owns no prerequisite activity. Its first useful work is a small JSON formatting step that depends on the shared workbook. The full JSON report remains strategic until that step works.",
          "recommendedEffort": {
            "lowMinutes": 30,
            "likelyMinutes": 45,
            "highMinutes": 60
          },
          "phases": [
            {
              "localId": "json_report",
              "title": "JSON totals report",
              "outcome": "You convert the category totals from the shared workbook into a JSON object and write it to a file."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Shared prerequisite owned and taught by plan_1; plan_2 consumes it without duplicating the workbook."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "JSON output target; depends on the shared loops-and-dictionaries workbook before formatting totals as JSON."
          }
        ],
        "activities": [
          {
            "localId": "json_totals",
            "outcomeRefs": [
              "json_report"
            ],
            "scopeRefs": [
              "scope_2"
            ],
            "title": "JSON expenses report from category totals",
            "activityType": "Coding task",
            "purpose": "Turn the category totals you already computed into a JSON report file, using the shared prerequisite.",
            "instructions": "Use the totals dictionary you built in the shared workbook (food 20, travel 30, books 20). 1) Import json. 2) Build a dictionary report = {'expenses': totals, 'grand_total': 70}. 3) Use json.dumps(report, indent=2) and print it. 4) Write it to expenses_report.json. 5) Open the file and check that the keys and numbers match your totals. If you need to rebuild totals, reuse the loop from the shared workbook rather than rewriting it from scratch.",
            "completionCriterion": "expenses_report.json contains the correct category totals and grand total, and printing the JSON shows the same numbers.",
            "effort": {
              "lowMinutes": 30,
              "likelyMinutes": 45,
              "highMinutes": 60
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "You will complete the shared loops-and-dictionaries workbook in plan_1 before starting this JSON step.",
            "You can write files in your working directory."
          ],
          "tradeOffs": [
            "No prerequisite activity is booked here, because duplicating the shared workbook would waste effort and violate the single-owner requirement.",
            "The JSON activity is kept small so it can run immediately after the shared checkpoint."
          ],
          "unresolvedUncertainty": [
            "The final JSON schema for the full report is not specified; this step uses a simple expenses and grand_total object that can be extended later."
          ],
          "stoppingConditions": [
            "Stop after expenses_report.json contains the correct totals and grand total.",
            "Do not add extra report fields until the basic JSON file is correct."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "loops_dict_workbook"
      },
      "dependent": {
        "planRef": "plan_2",
        "activityId": "json_totals"
      },
      "strength": "HARD",
      "reason": "The JSON report needs the loops-and-dictionary totals from the shared workbook; plan_2 does not duplicate that prerequisite."
    }
  ],
  "tradeOffExplanation": "The shared loops-and-dictionaries prerequisite is owned once by plan_1 as one small workbook, and plan_2 depends on it instead of repeating it. This delays CSV and JSON formatting until the prerequisite works, which is the right trade-off because you are new to both loops and dictionaries. The full CSV and JSON report targets remain strategic and unbooked until the shared checkpoint is demonstrated."
}

